(r, big) => {
    const operands = big ? 5000 : r.int(1, 7), lo = big ? -200 : -9, hi = big ? 200 : 9;
    const tokens = [], vals = [];
    const LIM = 1000000000;
    let left = operands;
    const reduce = () => {
      const b = vals.pop(), a = vals.pop();
      for (const op of r.shuffle(["+", "-", "*", "/"])) {
        if (op === "/" && b === 0) continue;
        const v = op === "+" ? a + b : op === "-" ? a - b : op === "*" ? a * b : Math.trunc(a / b);
        if (Math.abs(v) > LIM) continue;
        tokens.push(op); vals.push(v === 0 ? 0 : v);
        return;
      }
    };
    while (left > 0 || vals.length > 1) {
      if (left > 0 && (vals.length < 2 || r.bool(0.55))) { const x = r.int(lo, hi); tokens.push(String(x)); vals.push(x); left--; }
      else reduce();
    }
    return [tokens];
  }

