function evalPostfix(tokens: string[]): number {
  const stack: number[] = [];
  for (const t of tokens) {
    if (t !== "+" && t !== "-" && t !== "*" && t !== "/") {
      stack.push(Number(t));
      continue;
    }
    const b = stack.pop()!, a = stack.pop()!; // b is the right operand
    if (t === "+") stack.push(a + b);
    else if (t === "-") stack.push(a - b);
    else if (t === "*") stack.push(a * b);
    else stack.push(Math.trunc(a / b));
  }
  return stack[0];
}

