class Solution:
    def evalPostfix(self, tokens: List[str]) -> int:
        stack = []
        for t in tokens:
            if t not in ("+", "-", "*", "/"):
                stack.append(int(t))
                continue
            b = stack.pop()
            a = stack.pop()  # b is the right operand
            if t == "+":
                stack.append(a + b)
            elif t == "-":
                stack.append(a - b)
            elif t == "*":
                stack.append(a * b)
            else:
                # // floors; divide the sizes and put the sign back to truncate toward zero
                q = abs(a) // abs(b)
                stack.append(q if (a < 0) == (b < 0) else -q)
        return stack[0]

