import sys


class Solution:
    def evalPostfix(self, tokens: List[str]) -> int:
        sys.setrecursionlimit(max(1000, 2 * len(tokens) + 100))
        self.i = len(tokens) - 1

        def solve() -> int:
            t = tokens[self.i]
            self.i -= 1
            if t not in ("+", "-", "*", "/"):
                return int(t)
            b = solve()  # the right operand comes first when reading backwards
            a = solve()
            if t == "+":
                return a + b
            if t == "-":
                return a - b
            if t == "*":
                return a * b
            return int(a / b)  # exact here: |values| stay far below 2^53

        return solve()

